package coverage

import (
	"bufio"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"slices"
	"sort"
	"strconv"
	"strings"
	"sync"
)

// Profile holds which source lines are covered by tests.
type Profile struct {
	// key: relative file path from module root (e.g. "mutator/expr/foo.go")
	coveredLines map[string]map[int]bool
	resolved     sync.Map
}

// ParseProfile parses a Go coverage profile (generated by go test -coverprofile)
// using modulePath to strip the module prefix from each entry, leaving relative
// paths that can be matched against absolute file paths.
//
// Example: with modulePath="github.com/acme/app", the profile entry
// "github.com/acme/app/pkg/foo.go:5.1,10.3 2 1" becomes key "pkg/foo.go".
func ParseProfile(path, modulePath string) (*Profile, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	p := &Profile{coveredLines: make(map[string]map[int]bool)}
	prefix := modulePath + "/"
	scanner := bufio.NewScanner(f)
	for scanner.Scan() {
		line := scanner.Text()
		if strings.HasPrefix(line, "mode:") {
			continue
		}
		if err := p.parseLine(line, prefix); err != nil {
			return nil, fmt.Errorf("coverage parse %q: %w", line, err)
		}
	}
	return p, scanner.Err()
}

// longestSuffixKey returns the key from m that is the most specific path
// suffix of absFile and whether a key matched. An empty key can match only an
// empty absFile; the boolean distinguishes that match from no match. A
// non-empty key matches when it equals absFile or absFile ends in "/"+key.
// When multiple keys match — one relPath is a path-suffix of another, e.g.
// "foo/bar.go" and "bar.go" — the longest (most specific) key wins, so the
// choice is deterministic regardless of map iteration order. Ties are
// impossible because map keys are unique: two distinct strings of equal
// length cannot both be a suffix of the same path.
func longestSuffixKey[V any](absFile string, m map[string]V) (string, bool) {
	var best string
	var found bool
	for relPath := range m {
		if relPath == absFile || (relPath != "" && strings.HasSuffix(absFile, "/"+relPath)) {
			if !found || len(relPath) > len(best) {
				best = relPath
				found = true
			}
		}
	}
	return best, found
}

// IsCovered reports whether the given absolute file path and line number are
// reached by any test. The match uses the relative path suffix of absFile
// against the module-relative keys stored in the profile.
//
// When more than one key matches (one relPath is a path-suffix of another,
// e.g. "foo/bar.go" and "bar.go"), the longest — most specific — match wins,
// so resolution is deterministic regardless of map iteration order.
func (p *Profile) IsCovered(absFile string, line int) bool {
	absFile = filepath.ToSlash(absFile)
	if cached, ok := p.resolved.Load(absFile); ok {
		return cached.(map[int]bool)[line]
	}
	relPath, found := longestSuffixKey(absFile, p.coveredLines)
	var lines map[int]bool
	if found {
		lines = p.coveredLines[relPath]
	}
	p.resolved.Store(absFile, lines)
	return lines[line]
}

// IsCoveredRelative performs a direct lookup with a module-relative path.
func (p *Profile) IsCoveredRelative(relFile string, line int) bool {
	return p.coveredLines[filepath.ToSlash(relFile)][line]
}

// IsLineCoveredAnywhere reports whether any file in the profile has line
// recorded as covered. It is a last-resort fallback for //line-directive
// positions whose coverage block was filed under a different filename than
// either the physical file or the directive filename of the mutation (this
// happens when a single coverage block spans a //line filename change).
// Callers MUST gate this on a directive-shifted position; without a filename
// anchor it is too loose for general use.
func (p *Profile) IsLineCoveredAnywhere(line int) bool {
	if line <= 0 {
		return false
	}
	for _, lines := range p.coveredLines {
		if lines[line] {
			return true
		}
	}
	return false
}

// parseLine parses one data line from a coverage profile and strips modulePfx
// from the file name before storing coverage data.
// Format: file:startLine.startCol,endLine.endCol stmtCount hitCount
func (p *Profile) parseLine(line, modulePfx string) error {
	colonIdx := strings.LastIndex(line, ":")
	if colonIdx < 0 {
		return nil
	}
	relFile := relativeCoverageFile(line[:colonIdx], modulePfx)

	fields := strings.Fields(line[colonIdx+1:])
	if len(fields) != 3 {
		return nil
	}

	hitCount, err := strconv.Atoi(fields[2])
	if err != nil {
		return err
	}
	if hitCount == 0 {
		return nil
	}

	lines, err := parseCoverageRange(fields[0])
	if err != nil || lines == nil {
		return err
	}

	p.recordCoveredLines(relFile, lines.start, lines.end)
	return nil
}

// relativeCoverageFile strips modulePfx from a coverage file path, falling back
// to the raw path when the prefix is absent, and normalises separators.
func relativeCoverageFile(rawFile, modulePfx string) string {
	relFile := strings.TrimPrefix(rawFile, modulePfx)
	if relFile == rawFile {
		// Module prefix not present — use the raw path as-is.
		relFile = rawFile
	}
	return filepath.ToSlash(relFile)
}

// lineRange is an inclusive span of source lines.
type lineRange struct {
	start, end int
}

// parseCoverageRange parses the "startLine.startCol,endLine.endCol" range field.
// It returns nil (with a nil error) when the field is malformed and should be
// skipped rather than treated as an error.
func parseCoverageRange(field string) (*lineRange, error) {
	rangeParts := strings.SplitN(field, ",", 2)
	if len(rangeParts) != 2 {
		return nil, nil
	}
	startLine, err := parseLineNum(rangeParts[0])
	if err != nil {
		return nil, err
	}
	endLine, err := parseLineNum(rangeParts[1])
	if err != nil {
		return nil, err
	}
	return &lineRange{start: startLine, end: endLine}, nil
}

// recordCoveredLines marks lines [startLine, endLine] of relFile as covered.
func (p *Profile) recordCoveredLines(relFile string, startLine, endLine int) {
	if _, ok := p.coveredLines[relFile]; !ok {
		p.coveredLines[relFile] = make(map[int]bool)
	}
	for l := startLine; l <= endLine; l++ {
		p.coveredLines[relFile][l] = true
	}
}

// parseLineNum extracts the line number from "line.col" notation.
func parseLineNum(s string) (int, error) {
	parts := strings.SplitN(s, ".", 2)
	return strconv.Atoi(parts[0])
}

// PerTestProfile maps each (module-relative file path, line) to the sorted list
// of test function names that cover it.  Callers look up by absolute file path
// using CoveringTests; the match is done via suffix so it survives GOPATH/module
// root variations.
type PerTestProfile struct {
	// relPath → line → []testName (sorted)
	data     map[string]map[int][]string
	resolved sync.Map
}

// CoveringTests returns the sorted test names that cover absFile at lineNum.
// Returns nil when the line is not covered by any individually-run test.
//
// When more than one key matches (one relPath is a path-suffix of another),
// the longest — most specific — match wins, so resolution is deterministic
// regardless of map iteration order.
func (p *PerTestProfile) CoveringTests(absFile string, lineNum int) []string {
	if p == nil || lineNum <= 0 {
		return nil
	}
	absSlash := filepath.ToSlash(absFile)
	if cached, ok := p.resolved.Load(absSlash); ok {
		return cached.(map[int][]string)[lineNum]
	}
	relPath, found := longestSuffixKey(absSlash, p.data)
	var lines map[int][]string
	if found {
		lines = p.data[relPath]
	}
	p.resolved.Store(absSlash, lines)
	return lines[lineNum]
}

// CoveringTestsRelative performs a direct lookup with a module-relative path.
func (p *PerTestProfile) CoveringTestsRelative(relFile string, lineNum int) []string {
	if p == nil || lineNum <= 0 {
		return nil
	}
	return p.data[filepath.ToSlash(relFile)][lineNum]
}

// Toolchain builds the commands that per-test profiling runs. The caller
// owns how the user's test flags reach each command.
type Toolchain interface {
	// ListTests lists the top-level tests of pkgPath, one per line.
	ListTests(pkgPath string) *exec.Cmd
	// ListPackages lists the import paths matching pattern.
	ListPackages(pattern string) *exec.Cmd
	// CompileTestBinary writes pkgPath's test binary to binaryPath,
	// instrumented for -coverpkg=coverPkg.
	CompileTestBinary(pkgPath, coverPkg, binaryPath string) *exec.Cmd
	// RunTest runs testName from binaryPath, writing its coverage profile
	// to profilePath.
	RunTest(binaryPath, testName, profilePath string) *exec.Cmd
}

// CountTests returns the number of test functions (Test*, Fuzz*)
// in pkgPath. Returns 0 on any error or when the package has no tests.
func CountTests(tc Toolchain, pkgPath string) int {
	names, err := ListTests(tc, pkgPath)
	if err != nil {
		return 0
	}
	return len(names)
}

// ListTests returns runnable top-level Test and Fuzz entrypoint names.
func ListTests(tc Toolchain, pkgPath string) ([]string, error) {
	out, err := tc.ListTests(pkgPath).Output()
	if err != nil {
		return nil, err
	}
	var names []string
	for _, line := range strings.Split(strings.TrimSpace(string(out)), "\n") {
		line = strings.TrimSpace(line)
		if isTestFuncName(line) {
			names = append(names, line)
		}
	}
	return names, nil
}

// isTestFuncName reports whether name is a top-level test entry point that can
// be selected with go test's -run flag (Test* or Fuzz*).
func isTestFuncName(name string) bool {
	return strings.HasPrefix(name, "Test") ||
		strings.HasPrefix(name, "Fuzz")
}

// TestPackage names one package and the runnable top-level tests it declares.
type TestPackage struct {
	ImportPath string
	Tests      []string
}

// ListTestPackages returns the runnable tests of pkgPath. With recursive it
// also returns those of every package beneath pkgPath, matching the pkgPath/...
// target that --test-recursive gives mutant runs. Packages without tests are
// left out.
func ListTestPackages(tc Toolchain, pkgPath string, recursive bool) ([]TestPackage, error) {
	paths := []string{pkgPath}
	if recursive {
		var err error
		if paths, err = listPackages(tc, pkgPath+"/..."); err != nil {
			return nil, err
		}
	}
	var pkgs []TestPackage
	for _, path := range paths {
		names, err := ListTests(tc, path)
		if err != nil {
			return nil, err
		}
		if len(names) > 0 {
			pkgs = append(pkgs, TestPackage{ImportPath: path, Tests: names})
		}
	}
	return pkgs, nil
}

func listPackages(tc Toolchain, pattern string) ([]string, error) {
	out, err := tc.ListPackages(pattern).Output()
	if err != nil {
		return nil, err
	}
	return strings.Fields(string(out)), nil
}

// BuildPerTestProfile runs each test function in pkgPath individually with
// -coverprofile to build a map of which lines each test covers.  It uses up
// to workers goroutines in parallel.  Returns nil on any hard failure (the
// caller falls back to the full test suite).
//
// tc builds the list, compile and run commands, so flags such as -tags, -short
// and -race are consistent between profile-building and mutation test runs.
func BuildPerTestProfile(tc Toolchain, pkgPath, modulePath, tmpDir string, workers int) (*PerTestProfile, error) {
	// List test functions (not subtests).
	testNames, err := ListTests(tc, pkgPath)
	if err != nil {
		return nil, fmt.Errorf("go test -list: %w", err)
	}
	return BuildPerTestProfileForTests(tc, pkgPath, modulePath, tmpDir, workers, testNames)
}

// BuildPerTestProfileForTests builds a profile from an already-discovered test
// list, avoiding a second go test -list invocation in callers that show counts.
func BuildPerTestProfileForTests(tc Toolchain, pkgPath, modulePath, tmpDir string, workers int, testNames []string) (*PerTestProfile, error) {
	if len(testNames) == 0 {
		return nil, nil
	}
	pkgs := []TestPackage{{ImportPath: pkgPath, Tests: testNames}}
	return BuildPerTestProfileForPackages(tc, pkgPath, pkgs, modulePath, tmpDir, workers)
}

// BuildPerTestProfileForPackages builds one profile from the tests of every
// package in pkgs, as listed by ListTestPackages. Each test binary is built
// with -coverpkg=pkgPath, so tests in subpackages are credited with the
// pkgPath lines they cover.
func BuildPerTestProfileForPackages(tc Toolchain, pkgPath string, pkgs []TestPackage, modulePath, tmpDir string, workers int) (*PerTestProfile, error) {
	if len(pkgs) == 0 {
		return nil, nil
	}
	var jobs []perTestJob
	for _, pkg := range pkgs {
		binaryPath, err := compileCoverageTestBinary(tc, pkg.ImportPath, pkgPath, tmpDir)
		if err != nil {
			return nil, err
		}
		for _, name := range pkg.Tests {
			jobs = append(jobs, perTestJob{name: name, binaryPath: binaryPath})
		}
	}
	if workers <= 0 {
		workers = 1
	}
	results := profileTests(tc, jobs, workers, modulePath)
	return mergePerTestProfiles(results, len(jobs)), nil
}

// perTestJob is a work item for a per-test profiling worker.
type perTestJob struct {
	name       string
	binaryPath string
}

// perTestResult carries the coverage profile produced by one worker.
type perTestResult struct {
	name string
	prof *Profile
}

func compileCoverageTestBinary(tc Toolchain, pkgPath, coverPkg, tmpDir string) (string, error) {
	binaryDir := filepath.Join(tmpDir, "per-test", strings.NewReplacer("/", "_", "\\", "_").Replace(pkgPath))
	if err := os.MkdirAll(binaryDir, 0755); err != nil {
		return "", err
	}
	binaryPath := filepath.Join(binaryDir, "tests")
	if output, err := tc.CompileTestBinary(pkgPath, coverPkg, binaryPath).CombinedOutput(); err != nil {
		return "", fmt.Errorf("compile coverage test binary: %w: %s", err, output)
	}
	return binaryPath, nil
}

func profileTests(tc Toolchain, jobList []perTestJob, workers int, modulePath string) <-chan perTestResult {
	jobs := make(chan perTestJob, len(jobList))
	results := make(chan perTestResult, len(jobList))
	for i := 0; i < workers; i++ {
		go runPerTestWorker(tc, jobs, results, modulePath)
	}
	for _, job := range jobList {
		jobs <- job
	}
	close(jobs)
	return results
}

func mergePerTestProfiles(results <-chan perTestResult, count int) *PerTestProfile {
	p := &PerTestProfile{data: make(map[string]map[int][]string)}
	for i := 0; i < count; i++ {
		applyPerTestResult(p, <-results)
	}
	for _, lines := range p.data {
		for line, names := range lines {
			sort.Strings(names)
			lines[line] = slices.Compact(names)
		}
	}
	return p
}

// runPerTestWorker writes each test's profile beside its binary, so tests that
// share a name across packages do not overwrite each other's profiles.
func runPerTestWorker(tc Toolchain, jobs <-chan perTestJob, results chan<- perTestResult, modulePath string) {
	for job := range jobs {
		profDir := filepath.Join(filepath.Dir(job.binaryPath), job.name)
		_ = os.MkdirAll(profDir, 0755)
		profPath := filepath.Join(profDir, "coverage.out")

		_ = tc.RunTest(job.binaryPath, job.name, profPath).Run() // test failures are expected; we only care about coverage

		prof, err := ParseProfile(profPath, modulePath)
		if err != nil {
			results <- perTestResult{name: job.name, prof: nil}
			continue
		}
		results <- perTestResult{name: job.name, prof: prof}
	}
}

func applyPerTestResult(p *PerTestProfile, r perTestResult) {
	if r.prof == nil {
		return
	}
	for relPath, lines := range r.prof.coveredLines {
		if p.data[relPath] == nil {
			p.data[relPath] = make(map[int][]string)
		}
		for line := range lines {
			p.data[relPath][line] = append(p.data[relPath][line], r.name)
		}
	}
}
